'use strict';

// MODULES //

var abs = require( '@stdlib/math/base/special/abs' );
var min = require( '@stdlib/math/base/special/min' );
var max = require( '@stdlib/math/base/special/max' );


// MAIN //

/**
* Selects native only for conservative signed32 original metadata.
* @private
* @param {integer} uplo - numeric triangle
* @param {NonNegativeInteger} N - order
* @param {NonNegativeInteger} KD - bandwidth
* @param {Float64Array} AB - band view
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - band offset
* @param {Float64Array} S - vector output
* @param {integer} ss - vector stride
* @param {integer} os - vector offset
* @param {Float64Array} SCOND - scalar output
* @param {integer} oc - scalar offset
* @param {Float64Array} AMAX - scalar output
* @param {integer} om - scalar offset
* @returns {boolean} eligibility
*/
function eligible( uplo, N, KD, AB, r, c, o, S, ss, os, SCOND, oc, AMAX, om ) { // eslint-disable-line max-params -- Preserve the adopted fourteen-argument ndarray contract.
	var args = [ uplo, N, KD, r, c, o, ss, os, oc, om ];
	var MAX = 2147483647;
	var dr;
	var dc;
	var ds;
	var i;
	if ( N === 0 ) {
		return ((oc <= MAX) && (om <= MAX));
	}
	for ( i = 0; i < args.length; i++ ) {
		if ( abs(args[i]) > MAX ) {
			return false;
		}
	}
	if ( N === 0 ) {
		return true;
	}
	dr = KD*r;
	dc = (N-1)*c;
	ds = (N-1)*ss;
	if ( abs(dr) > MAX || abs(dc) > MAX || abs(ds) > MAX ) {
		return false;
	}
	return o+min(dr, 0)+min(dc, 0) >= 0 && o+max(dr, 0)+max(dc, 0) <= MAX && os+min(ds, 0) >= 0 && os+max(ds, 0) <= MAX;
}


// EXPORTS //

module.exports = eligible;
